#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int maxn=6000;
const int inf=INT_MAX;
const ll inff=1e18;
#define pii pair<int,int>
#define mkp make_pair
#define F first
#define S second
#define pb push_back
#define sz(v) ((int)(v).size())
#define all(v) (v).begin(),(v).end()
#define IOS ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
#define int ll
// #define endl '\n'

int total_nodes,n,s,t;
struct edge
{
    int to,cap,cost,rev;
};
vector<edge> graph[maxn];
int dist[maxn];
int parent_node[maxn],parent_edge[maxn];
int in_queue[maxn];

void setup(int _nodes,int _source,int _sink)
{
    for (int i=0;i<=_nodes;i++) graph[i].clear();
    total_nodes=_nodes;
    s=_source;
    t=_sink;
}

void add_link(int from,int to,int capacity,int cost)
{
    graph[from].push_back({to,capacity,cost,(int)graph[to].size()});
    graph[to].push_back({from,0,-cost,(int)graph[from].size()-1});
}

int min_cost_max_flow(int flow_needed)
{
    int total_cost=0;
    while (flow_needed>0)
    {
        fill(dist,dist+total_nodes,inff);
        dist[s]=0;
        queue<int> q;
        q.push(s);
        in_queue[s]=1;
        while (!q.empty())
        {
            int u=q.front();
            q.pop();
            in_queue[u]=0;
            for (int i=0;i<sz(graph[u]);i++)
            {
                auto &e=graph[u][i];
                if (e.cap>0&&dist[u]+e.cost<dist[e.to])
                {
                    dist[e.to]=dist[u]+e.cost;
                    parent_node[e.to]=u;
                    parent_edge[e.to]=i;
                    if (!in_queue[e.to]) { in_queue[e.to]=1; q.push(e.to); }
                }
            }
        }

        if (dist[t]==inff) return -1;

        int flow_delta=flow_needed;
        for (int v=t;v!=s;v=parent_node[v])
        {
            flow_delta=min(flow_delta,graph[parent_node[v]][parent_edge[v]].cap);
        }
        flow_needed-=flow_delta;
        total_cost+=flow_delta*dist[t];
        for (int v=t;v!=s;v=parent_node[v])
        {
            auto &e=graph[parent_node[v]][parent_edge[v]];
            e.cap-=flow_delta;
            graph[v][e.rev].cap+=flow_delta;
        }
    }
    return total_cost;
}

int N,M,K,C,D,X,Y;
int A[58];
vector<int> H[57];

int main()
{
    IOS
    cin>>N>>M>>K>>C>>D;
    for (int i=1;i<=K;i++)
    {
        cin>>X;
        A[X]++;
    }
    for (int i=1;i<=M;i++)
    {
        cin>>X>>Y;
        H[X].push_back(Y);
        H[Y].push_back(X);
    }

    setup(5103,0,5101);
    for (int i=2;i<=N;i++) add_link(0,i,A[i],0);
    for (int i=0;i<=100;i++)
    {
        for (int l=1;l<=N;l++)
        {
            add_link(50*i+l,50*(i+1)+l,K,0);
            for (int j:H[l])
            {
                for (int k=1;k<=K;k++)
                {
                    add_link(50*i+l,50*(i+1)+j,1,D*(2*k-1));
                }
            }
        }
    }
    for (int i=1;i<=101;i++) add_link(50*i+1,5101,K,C*i);
    cout<<min_cost_max_flow(K)<<endl;
}
